-- Safe division using NULLIF to avoid a divide-by-zero error
SELECT SalesAmount / NULLIF(UnitsSold, 0) AS AvgPricePerUnit
FROM Sales.SalesSummary;

-- Simple form: equality against one column only
SELECT Name, CASE Size WHEN 'S' THEN 'Small' WHEN 'M' THEN 'Medium' ELSE 'Other' END
FROM Production.Product;

-- Safer equivalent using NOT EXISTS, immune to the NULL trap
SELECT p.Name FROM Production.Product p
WHERE NOT EXISTS (
  SELECT 1 FROM Sales.SalesOrderDetail sod WHERE sod.ProductID = p.ProductID
);

