SELECT [Black], [Blue], [Red], [Silver]
FROM (SELECT Color, ListPrice FROM Production.Product) AS SourceTable
PIVOT (
  AVG(ListPrice) FOR Color IN ([Black], [Blue], [Red], [Silver])
) AS PivotTable;

CREATE PROCEDURE usp_InsertProduct
  @ProductID INT, @Name NVARCHAR(50), @ListPrice MONEY
AS
BEGIN
  BEGIN TRY
    INSERT INTO Products (ProductID, Name, ListPrice)
    VALUES (@ProductID, @Name, @ListPrice);
  END TRY
  BEGIN CATCH
    SELECT ERROR_NUMBER() AS ErrorNumber, ERROR_MESSAGE() AS ErrorMessage;
  END CATCH
END;
